#pragma once
#define BATTERIES_TAGGED_PTR_HPP

#include <batteries/config.hpp>
//
#if BATT_CPP_20

#include <batteries/case_of.hpp>
#include <batteries/int_types.hpp>
#include <batteries/math.hpp>
#include <batteries/optional.hpp>
#include <batteries/tuples.hpp>

#include <concepts>
#include <tuple>
#include <variant>

namespace batt {

template <typename... CasesT>
class TaggedPtr
{
   public:
    using Self = TaggedPtr;

    static constexpr usize kSize = sizeof...(CasesT);

    static constexpr usize kTagBits = log2_ceil(kSize);

    static constexpr usize kTagShift = (8 * sizeof(uptr)) - kTagBits;

    static constexpr uptr kTagMask = ~uptr{0} << kTagShift;

    static constexpr uptr kPtrMask = ~kTagMask;

    using VariantT = std::variant<NoneType, std::add_pointer_t<CasesT>...>;

    using TupleT = std::tuple<NoneType, std::add_pointer_t<CasesT>...>;

    //----- --- -- -  -  -   -

    template <usize kIndex>
    static constexpr StaticType<std::tuple_element_t<kIndex, TupleT>> get_case_type(
        std::integral_constant<usize, kIndex> /*index*/ = {}) noexcept
    {
        return {};
    }

    template <usize kIndex>
    using GetCaseType = typename decltype(get_case_type<kIndex>())::type;

    static constexpr usize size() noexcept
    {
        return Self::kSize;
    }

    template <typename CaseT>
        requires(std::is_same_v<CaseT, NoneType>)
    static constexpr usize case_index(StaticType<CaseT> /*case_type*/ = {}) noexcept
    {
        return 0;
    }

    template <typename CaseT>
        requires(!std::is_same_v<CaseT, NoneType>)
    static constexpr usize case_index(StaticType<CaseT> /*case_type*/ = {}) noexcept
    {
        return TupleIndexOf<TupleT, std::add_pointer_t<CaseT>>::value;
    }

    template <typename CaseT>
    static constexpr uptr case_tag(StaticType<CaseT> case_type = {}) noexcept
    {
        return Self::case_tag(Self::case_index(case_type));
    }

    static constexpr uptr case_tag(usize case_i) noexcept
    {
        return (case_i - 1) << kTagShift;
    }

    template <typename CaseT>
    static constexpr bool is_valid_case() noexcept
    {
        return Self::case_index<CaseT>() < (Self::kSize + /*NoneType*/ 1);
    }

    //----- --- -- -  -  -   -

    TaggedPtr(NoneType) noexcept : value_{0}
    {
    }

    TaggedPtr() noexcept : Self{None}
    {
    }

    TaggedPtr(const TaggedPtr&) = default;
    TaggedPtr& operator=(const TaggedPtr&) = default;

    template <typename CaseT>
        requires(is_valid_case<CaseT>())
    /*implicit*/ TaggedPtr(CaseT* case_ptr) noexcept
        : value_{Self::case_tag<CaseT>() | (reinterpret_cast<uptr>(case_ptr) & Self::kPtrMask)}
    {
        BATT_CHECK_EQ(this->ptr_value(), (const void*)case_ptr);
    }

    //----- --- -- -  -  -   -

    const void* ptr_value() const noexcept
    {
        return reinterpret_cast<const void*>(this->value_ & Self::kPtrMask);
    }

    uptr int_value() const noexcept
    {
        return this->value_;
    }

    uptr tag() const noexcept
    {
        return this->value_ & Self::kTagMask;
    }

    template <typename... CaseFns, typename Visitor = CaseOfVisitor<CaseFns&&...>,
              typename Result = detail::VisitorResultT<Visitor, Self::VariantT>>
        requires(kSize == 2)
    Result visit(CaseFns&&... case_fns) const noexcept
    {
        auto visitor = Visitor{BATT_FORWARD(case_fns)...};

        if (this->value_ == 0) {
            return visitor(None);
        }

        switch (this->tag()) {
        case Self::case_tag(1):
            return visitor(reinterpret_cast<GetCaseType<1>>(this->value_ & kPtrMask));

        case Self::case_tag(2):
            return visitor(reinterpret_cast<GetCaseType<2>>(this->value_ & kPtrMask));

        default:
            break;
        }

        BATT_PANIC() << "bad tag:" << BATT_INSPECT(this->value_);
        BATT_UNREACHABLE();
    }

    template <typename... CaseFns, typename Visitor = CaseOfVisitor<CaseFns&&...>,
              typename Result = detail::VisitorResultT<Visitor, Self::VariantT>>
        requires(kSize == 3)
    Result visit(CaseFns&&... case_fns) const noexcept
    {
        auto visitor = Visitor{BATT_FORWARD(case_fns)...};

        if (this->value_ == 0) {
            return visitor(None);
        }

        switch (this->tag()) {
        case Self::case_tag(1):
            return visitor(reinterpret_cast<GetCaseType<1>>(this->value_ & kPtrMask));

        case Self::case_tag(2):
            return visitor(reinterpret_cast<GetCaseType<2>>(this->value_ & kPtrMask));

        case Self::case_tag(3):
            return visitor(reinterpret_cast<GetCaseType<3>>(this->value_ & kPtrMask));

        default:
            break;
        }

        BATT_PANIC() << "bad tag:" << BATT_INSPECT(this->value_);
        BATT_UNREACHABLE();
    }

    template <typename... CaseFns, typename Visitor = CaseOfVisitor<CaseFns&&...>,
              typename Result = detail::VisitorResultT<Visitor, Self::VariantT>>
        requires(kSize == 4)
    Result visit(CaseFns&&... case_fns) const noexcept
    {
        auto visitor = Visitor{BATT_FORWARD(case_fns)...};

        if (this->value_ == 0) {
            return visitor(None);
        }

        switch (this->tag()) {
        case Self::case_tag(1):
            return visitor(reinterpret_cast<GetCaseType<1>>(this->value_ & kPtrMask));

        case Self::case_tag(2):
            return visitor(reinterpret_cast<GetCaseType<2>>(this->value_ & kPtrMask));

        case Self::case_tag(3):
            return visitor(reinterpret_cast<GetCaseType<3>>(this->value_ & kPtrMask));

        case Self::case_tag(4):
            return visitor(reinterpret_cast<GetCaseType<4>>(this->value_ & kPtrMask));

        default:
            break;
        }

        BATT_PANIC() << "bad tag:" << BATT_INSPECT(this->value_);
        BATT_UNREACHABLE();
    }

   private:
    uptr value_;
};

}  // namespace batt

#endif  // BATT_CPP_20
